import React from 'react';

export default function Teachers() {
  const teacherDetails = [
    { name: "නලින්ද ජයසිංහ", sub: "Mathematics", degree: "B.Sc. (Mathematics) - UOC", tel: "077-3456789" },
    { name: "බුද්ධිකා දර්ශනී", sub: "Science / Maths", degree: "B.Sc. (Physical Science) - USJP", tel: "071-2345678" },
    { name: "ප්‍රසිද්ධ දිසානායක", sub: "Accounting", degree: "B.Sc. (Accounting) / ACA", tel: "071-8901234" },
    { name: "චාමර සර්", sub: "Commerce / BS", degree: "B.Sc. (Business Admin) - USJP", tel: "077-9012345" },
    { name: "මනෝජ් සර්", sub: "Physics", degree: "B.Sc. (Physics Special) - UOC", tel: "076-0123456" },
    { name: "සජිත් ගුණරත්න", sub: "Sinhala", degree: "BA (Hons) in Sinhala - UOK", tel: "076-4567890" }
  ];

  return (
    <div style={{ padding: '60px 20px', maxWidth: '1100px', margin: '0 auto' }}>
      <h2 style={{ textAlign: 'center', color: '#1e3a8a', marginBottom: '40px' }}>Our Expert Lecturers</h2>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: '25px' }}>
        {teacherDetails.map((t, idx) => (
          <div key={idx} style={{ backgroundColor: '#fff', padding: '30px', borderRadius: '15px', textAlign: 'center', boxShadow: '0 10px 20px rgba(0,0,0,0.05)', borderTop: '5px solid #059669' }}>
            <div style={{ fontSize: '50px', marginBottom: '15px' }}>👨‍🏫</div>
            <h3 style={{ margin: '0 0 5px 0', fontSize: '20px' }}>{t.name}</h3>
            <p style={{ color: '#059669', fontWeight: 'bold', margin: '0 0 15px 0' }}>{t.sub}</p>
            <div style={{ textAlign: 'left', fontSize: '14px', backgroundColor: '#f9fafb', padding: '15px', borderRadius: '10px' }}>
              <p style={{ margin: '0 0 8px 0' }}>🎓 <strong>Qualifications:</strong> <br/> {t.degree}</p>
              <p style={{ margin: 0 }}>📞 <strong>Contact:</strong> {t.tel}</p>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
